/* @lc app=leetcode id=4016 lang=kotlin */ class Solution { fun ok(ls: Array<IntArray>, k: Int): Boolean = ls.indices.flatMap { r -> ls[r].indices.filter { ls[r][it] >= k }.map { r to it } }.let { p -> p.isNotEmpty() && (p.maxOf { it.first } - p.minOf { it.first } >= k || p.maxOf { it.second } - p.minOf { it.second } >= k) } fun maxArea(mat: Array<IntArray>): Int = Array(mat.size) { IntArray(mat[0].size) }.also { ls -> mat.indices.forEach { i -> mat[0].indices.forEach { j -> ls[i][j] = if (mat[i][j] == 0) 0 else 1 + minOf(if (i > 0) ls[i - 1][j] else 0, if (j > 0) ls[i][j - 1] else 0, if (i > 0 && j > 0) ls[i - 1][j - 1] else 0) } } }.let { ls -> generateSequence(0 to minOf(mat.size, mat[0].size) + 1) { (lo, hi) -> if (hi - lo > 1) ((lo + hi) / 2).let { mid -> if (ok(ls, mid)) mid to hi else lo to mid } else null }.last().first.let { it * it } } }